class Solution {
public:
    double average(vector<int>& salary) {
        int min_val = salary[0];
        int max_val = salary[0];
        double sum = 0;

        for (int s : salary) {
            min_val = min(min_val, s);
            max_val = max(max_val, s);
            sum += s;
        }

        return (sum - min_val - max_val) / (salary.size() - 2);
    }
};
