#include <vector>
#include <string>

using namespace std;

class Solution {
    vector<string> getValid(const string& t) {
        vector<string> res;
        int n = t.length();
        if (n == 0) return res;

        // No decimal point
        if (n == 1 || t[0] != '0') {
            res.push_back(t);
        }

        // With decimal point
        for (int i = 1; i < n; ++i) {
            string integer_part = t.substr(0, i);
            string frac_part = t.substr(i);

            bool valid_int = (integer_part == "0" || integer_part[0] != '0');
            bool valid_frac = (frac_part.back() != '0');

            if (valid_int && valid_frac) {
                res.push_back(integer_part + "." + frac_part);
            }
        }
        return res;
    }

public:
    vector<string> ambiguousCoordinates(string s) {
        string S = s.substr(1, s.length() - 2);
        vector<string> ans;

        for (int i = 1; i < (int)S.length(); ++i) {
            vector<string> left = getValid(S.substr(0, i));
            vector<string> right = getValid(S.substr(i));

            for (const string& l : left) {
                for (const string& r : right) {
                    ans.push_back("(" + l + ", " + r + ")");
                }
            }
        }

        return ans;
    }
};
