#include <vector>
#include <numeric>
#include <algorithm>

using namespace std;

class Solution {
    struct DSU {
        vector<int> parent;
        vector<int> sz;

        DSU(int n) : parent(n), sz(n, 1) {
            iota(parent.begin(), parent.end(), 0);
        }

        int find(int i) {
            if (parent[i] == i)
                return i;
            return parent[i] = find(parent[i]);
        }

        void unite(int i, int j) {
            int root_i = find(i);
            int root_j = find(j);
            if (root_i != root_j) {
                parent[root_i] = root_j;
                sz[root_j] += sz[root_i];
            }
        }

        int size(int i) {
            return sz[find(i)];
        }
    };

public:
    vector<int> hitBricks(vector<vector<int>>& grid, vector<vector<int>>& hits) {
        int m = grid.size();
        int n = grid[0].size();

        // Copy grid to modify it
        vector<vector<int>> g = grid;
        for (const auto& hit : hits) {
            g[hit[0]][hit[1]] = 0;
        }

        int ceiling = m * n;
        DSU dsu(ceiling + 1);
        dsu.sz[ceiling] = 0;

        auto get_id = [&](int r, int c) {
            return r * n + c;
        };

        const int dr[] = {-1, 1, 0, 0};
        const int dc[] = {0, 0, -1, 1};

        // Build initial DSU with remaining bricks
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (g[r][c] == 1) {
                    int id = get_id(r, c);
                    if (r == 0) {
                        dsu.unite(id, ceiling);
                    }
                    if (r > 0 && g[r - 1][c] == 1) {
                        dsu.unite(id, get_id(r - 1, c));
                    }
                    if (c > 0 && g[r][c - 1] == 1) {
                        dsu.unite(id, get_id(r, c - 1));
                    }
                }
            }
        }

        int k = hits.size();
        vector<int> result(k, 0);

        for (int i = k - 1; i >= 0; --i) {
            int r = hits[i][0];
            int c = hits[i][1];

            // If there was no brick originally at this position
            if (grid[r][c] == 0) {
                continue;
            }

            int prev_roof = dsu.size(ceiling);
            int id = get_id(r, c);

            // Connect to ceiling if in the top row
            if (r == 0) {
                dsu.unite(id, ceiling);
            }

            // Connect to valid adjacent neighbors
            for (int d = 0; d < 4; ++d) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && g[nr][nc] == 1) {
                    dsu.unite(id, get_id(nr, nc));
                }
            }

            g[r][c] = 1;

            int cur_roof = dsu.size(ceiling);
            // If the restored brick is connected to ceiling, the bricks that fell
            // are those newly connected, minus the restored brick itself.
            result[i] = max(0, cur_roof - prev_roof - 1);
        }

        return result;
    }
};
```

