class Solution {
public:
    int clumsy(int n) {
        std::vector<int> st;
        st.push_back(n);
        int op = 0;

        for (int i = n - 1; i >= 1; --i) {
            if (op == 0) {
                st.back() *= i;
            } else if (op == 1) {
                st.back() /= i;
            } else if (op == 2) {
                st.push_back(i);
            } else {
                st.push_back(-i);
            }
            op = (op + 1) % 4;
        }

        int result = 0;
        for (int val : st) {
            result += val;
        }
        return result;
    }
};
