```cpp
#include <vector>
#include <queue>
#include <set>
#include <algorithm>

class MKAverage {
private:
    int m, k;
    long long sum_mid;
    std::queue<int> q;
    std::multiset<int> left, mid, right;

public:
    MKAverage(int m, int k) : m(m), k(k), sum_mid(0) {}

    void addElement(int num) {
        q.push(num);
        if (q.size() < m) {
            return;
        }
        if (q.size() == m) {
            std::vector<int> elements;
            std::queue<int> temp_q = q;
            while (!temp_q.empty()) {
                elements.push_back(temp_q.front());
                temp_q.pop();
            }
            std::sort(elements.begin(), elements.end());

            for (int i = 0; i < k; ++i) {
                left.insert(elements[i]);
            }
            for (int i = k; i < m - k; ++i) {
                mid.insert(elements[i]);
                sum_mid += elements[i];
            }
            for (int i = m - k; i < m; ++i) {
                right.insert(elements[i]);
            }
            return;
        }

        // Insert num
        if (num <= *left.rbegin()) {
            left.insert(num);
        } else if (num <= *mid.rbegin()) {
            mid.insert(num);
            sum_mid += num;
        } else {
            right.insert(num);
        }

        // Remove the oldest element
        int to_remove = q.front();
        q.pop();

        if (to_remove <= *left.rbegin()) {
            left.erase(left.find(to_remove));
        } else if (to_remove <= *mid.rbegin()) {
            mid.erase(mid.find(to_remove));
            sum_mid -= to_remove;
        } else {
            right.erase(right.find(to_remove));
        }

        // Rebalance left and mid
        if (left.size() < k) {
            int val = *mid.begin();
            mid.erase(mid.begin());
            sum_mid -= val;
            left.insert(val);
        } else if (left.size() > k) {
            int val = *left.rbegin();
            left.erase(std::prev(left.end()));
            mid.insert(val);
            sum_mid += val;
        }

        // Rebalance right and mid
        if (right.size() < k) {
            int val = *mid.rbegin();
            mid.erase(std::prev(mid.end()));
            sum_mid -= val;
            right.insert(val);
        } else if (right.size() > k) {
            int val = *right.begin();
            right.erase(right.begin());
            mid.insert(val);
            sum_mid += val;
        }
    }

    int calculateMKAverage() {
        if (q.size() < m) {
            return -1;
        }
        return sum_mid / (m - 2 * k);
    }
};

/**
 * Your MKAverage object will be instantiated and called as such:
 * MKAverage* obj = new MKAverage(m, k);
 * obj->addElement(num);
 * int param_2 = obj->calculateMKAverage();
 */
```

