using namespace std;

class Solution {
    int f(const string& s) {
        char min_c = 'z' + 1;
        int count = 0;
        for (char c : s) {
            if (c < min_c) {
                min_c = c;
                count = 1;
            } else if (c == min_c) {
                count++;
            }
        }
        return count;
    }

public:
    vector<int> numSmallerByFrequency(vector<string>& queries, vector<string>& words) {
        vector<int> count(12, 0);
        for (const string& w : words) {
            count[f(w)]++;
        }
        for (int i = 10; i >= 1; --i) {
            count[i] += count[i + 1];
        }

        vector<int> answer;
        answer.reserve(queries.size());
        for (const string& q : queries) {
            answer.push_back(count[f(q) + 1]);
        }

        return answer;
    }
};
