#include <vector>
#include <unordered_map>

using namespace std;

class Solution {
public:
    bool canCross(vector<int>& stones) {
        int n = stones.size();
        if (stones[1] != 1) return false;
        if (n == 2) return true;

        unordered_map<int, int> pos_to_idx;
        for (int i = 0; i < n; ++i) {
            pos_to_idx[stones[i]] = i;
        }

        vector<vector<bool>> dp(n, vector<bool>(n + 1, false));
        dp[1][1] = true;

        for (int i = 1; i < n; ++i) {
            for (int k = 1; k <= i; ++k) {
                if (!dp[i][k]) continue;
                for (int step = k - 1; step <= k + 1; ++step) {
                    if (step <= 0) continue;
                    int next_pos = stones[i] + step;
                    auto it = pos_to_idx.find(next_pos);
                    if (it != pos_to_idx.end()) {
                        int j = it->second;
                        if (j == n - 1) return true;
                        dp[j][step] = true;
                    }
                }
            }
        }

        return false;
    }
};
