class Solution {
public:
    int maxPoints(vector<vector<int>>& points) {
        int n = points.size();
        if (n <= 2) return n;

        int ans = 2;
        for (int i = 0; i < n; ++i) {
            map<pair<int, int>, int> slope_count;
            int cur_max = 0;
            for (int j = i + 1; j < n; ++j) {
                int dx = points[j][0] - points[i][0];
                int dy = points[j][1] - points[i][1];
                int g = std::gcd(dx, dy);
                dx /= g;
                dy /= g;
                if (dx < 0 || (dx == 0 && dy < 0)) {
                    dx = -dx;
                    dy = -dy;
                }
                cur_max = max(cur_max, ++slope_count[{dx, dy}]);
            }
            ans = max(ans, cur_max + 1);
        }

        return ans;
    }
};
