class Solution {
public:
    int countTriples(int n) {
        int count = 0;
        for (int a = 1; a <= n; ++a) {
            for (int b = 1; b <= n; ++b) {
                int sum_sq = a * a + b * b;
                int c = round(sqrt(sum_sq));
                if (c <= n && c * c == sum_sq) {
                    count++;
                }
            }
        }
        return count;
    }
};
