class Solution {
public:
    int countMaxOrSubsets(vector<int>& nums) {
        int max_or = 0;
        for (int x : nums) {
            max_or |= x;
        }

        int n = nums.size();
        auto dfs = [&](auto& self, int index, int current_or) -> int {
            if (current_or == max_or) {
                return 1 << (n - index);
            }
            if (index == n) {
                return 0;
            }
            return self(self, index + 1, current_or | nums[index]) +
                   self(self, index + 1, current_or);
        };

        return dfs(dfs, 0, 0);
    }
};
