#include <vector>
#include <numeric>
#include <algorithm>

using namespace std;

class Solution {
public:
    int maxScore(vector<int>& nums) {
        int m = nums.size();
        vector<vector<int>> g(m, vector<int>(m, 0));
        for (int i = 0; i < m; ++i) {
            for (int j = i + 1; j < m; ++j) {
                g[i][j] = std::gcd(nums[i], nums[j]);
            }
        }

        int total_masks = 1 << m;
        vector<int> dp(total_masks, 0);

        for (int mask = 0; mask < total_masks; ++mask) {
            int cnt = __builtin_popcount(mask);
            if (cnt % 2 != 0) continue;

            int op = cnt / 2 + 1;
            int i = 0;
            while (i < m && (mask & (1 << i))) {
                ++i;
            }
            if (i == m) continue;

            for (int j = i + 1; j < m; ++j) {
                if (!(mask & (1 << j))) {
                    int next_mask = mask | (1 << i) | (1 << j);
                    dp[next_mask] = max(dp[next_mask], dp[mask] + op * g[i][j]);
                }
            }
        }

        return dp[total_masks - 1];
    }
};
