    CustomStack(int maxSize) : max_size(maxSize), inc(maxSize, 0) {}

    void push(int x) {
        if (stk.size() < max_size) {
            stk.push_back(x);
        }
    }

    int pop() {
        int idx = (int)stk.size() - 1;
        if (idx < 0) {
            return -1;
        }
        if (idx > 0) {
            inc[idx - 1] += inc[idx];
        }
        int res = stk[idx] + inc[idx];
        inc[idx] = 0;
        stk.pop_back();
        return res;
    }

    void increment(int k, int val) {
        int idx = min((int)stk.size(), k) - 1;
        if (idx >= 0) {
            inc[idx] += val;
        }
    }
};

