    int maximumANDSum(vector<int>& nums, int numSlots) {
        vector<int> pow3(numSlots + 1, 1);
        for (int i = 1; i <= numSlots; ++i) {
            pow3[i] = pow3[i - 1] * 3;
        }

        int max_mask = pow3[numSlots];
        vector<int> dp(max_mask, -1);
        dp[0] = 0;

        int n = nums.size();
        int ans = 0;

        for (int mask = 0; mask < max_mask; ++mask) {
            if (dp[mask] < 0) continue;

            int count = 0;
            int temp = mask;
            for (int s = 0; s < numSlots; ++s) {
                count += temp % 3;
                temp /= 3;
            }

            if (count == n) {
                ans = max(ans, dp[mask]);
                continue;
            }

            temp = mask;
            for (int s = 0; s < numSlots; ++s) {
