class Solution {
public:
    int maxEqualFreq(vector<int>& nums) {
        vector<int> count(100005, 0);
        vector<int> freq(100005, 0);
        int max_f = 0;
        int ans = 0;

        for (int i = 0; i < nums.size(); ++i) {
            int x = nums[i];

            if (count[x] > 0) {
                freq[count[x]]--;
            }
            count[x]++;
            freq[count[x]]++;

            max_f = max(max_f, count[x]);
            int L = i + 1;

            bool valid = false;
            if (max_f == 1) {
                valid = true;
            } else if (freq[max_f] * max_f + 1 == L && freq[1] == 1) {
                valid = true;
            } else if (freq[max_f] == 1 && (freq[max_f - 1] + 1) * (max_f - 1) == L - 1) {
                valid = true;
            }

            if (valid) {
                ans = L;
            }
        }

        return ans;
    }
};
