class Solution {
public:
    int maxTotalFruits(vector<vector<int>>& fruits, int startPos, int k) {
        auto get_steps = [&](int pos_L, int pos_R) {
            if (pos_R <= startPos) {
                return startPos - pos_L;
            } else if (pos_L >= startPos) {
                return pos_R - startPos;
            } else {
                return (pos_R - pos_L) + min(startPos - pos_L, pos_R - startPos);
            }
        };

        int n = fruits.size();
        int left = 0;
        int current_sum = 0;
        int max_fruits = 0;

        for (int right = 0; right < n; ++right) {
            current_sum += fruits[right][1];
            while (left <= right && get_steps(fruits[left][0], fruits[right][0]) > k) {
                current_sum -= fruits[left][1];
                left++;
            }
            max_fruits = max(max_fruits, current_sum);
        }

        return max_fruits;
    }
};
