        int n = grid[0].size();

        vector<vector<long long>> rowPref(m, vector<long long>(n + 1, 0));
        vector<vector<long long>> colPref(m + 1, vector<long long>(n, 0));

        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                rowPref[i][j + 1] = rowPref[i][j] + grid[i][j];
                colPref[i + 1][j] = colPref[i][j] + grid[i][j];
            }
        }

        for (int k = min(m, n); k >= 2; --k) {
            for (int r = 0; r <= m - k; ++r) {
                for (int c = 0; c <= n - k; ++c) {
                    long long target = rowPref[r][c + k] - rowPref[r][c];
                    bool ok = true;

                    // Check rows
                    for (int i = 1; i < k; ++i) {
                        if (rowPref[r + i][c + k] - rowPref[r + i][c] != target) {
                            ok = false;
                            break;
                        }
                    }
                    if (!ok) continue;

                    // Check columns
                    for (int j = 0; j < k; ++j) {
                        if (colPref[r + k][c + j] - colPref[r][c + j] != target) {
                            ok = false;
                            break;
                        }
                    }
                    if (!ok) continue;

                    // Check main diagonal
                    long long d1 = 0;
                    for (int d = 0; d < k; ++d) {
                        d1 += grid[r + d][c + d];
                    }
                    if (d1 != target) continue;

                    // Check anti-diagonal
                    long long d2 = 0;
                    for (int d = 0; d < k; ++d) {
