An optimal and elegant way to solve this problem is using Dynamic Programming with Bitmasking.

### Method Explanation
The dimensions of the classroom are small ($m, n \le 8$), which suggests that we can represent the student seating arrangement of each row as a bitmask of length $n$. Since $2^n \le 256$, the number of states per row is very small.

For each row $r$:
1. A configuration $mask$ is valid if:
   - No two students are sitting next to each other horizontally: `(mask & (mask << 1)) == 0`.
   - Students only sit in broken-free seats (`.`): `(mask & ~valid_seats[r]) == 0`.
2. Transitioning from the previous row's configuration $prev\_mask$ to the current row's configuration $curr\_mask$:
   - A student at $(r, c)$ cannot see upper-left $(r-1, c-1)$, so `(curr_mask & (prev_mask << 1)) == 0`.
   - A student at $(r, c)$ cannot see upper-right $(r-1, c+1)$, so `(curr_mask & (prev_mask >> 1)) == 0`.

Let $dp[mask]$ denote the maximum number of students that can be seated up to the current row with the row's configuration being $mask$. We iterate through each row, update the DP table, and the answer will be the maximum value in the final DP table.

### C++ Source Code

```cpp
class Solution {
public:
    int maxStudents(vector<vector<char>>& seats) {
        int m = seats.size();
        int n = seats[0].size();

        vector<int> valid_seats(m, 0);
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (seats[i][j] == '.') {
                    valid_seats[i] |= (1 << j);
                }
            }
        }

        int total_masks = 1 << n;
        vector<int> dp(total_masks, -1);
        dp[0] = 0; // Base state before row 0

        for (int r = 0; r < m; ++r) {
            vector<int> next_dp(total_masks, -1);

            for (int curr_mask = 0; curr_mask < total_masks; ++curr_mask) {
                // Must only sit in available seats
                if ((curr_mask & ~valid_seats[r]) != 0) continue;
                // No two students adjacent in the same row
                if ((curr_mask & (curr_mask << 1)) != 0) continue;

                int students_in_curr = __builtin_popcount(curr_mask);

                for (int prev_mask = 0; prev_mask < total_masks; ++prev_mask) {
                    if (dp[prev_mask] == -1) continue;
                    // No student in upper-left
                    if ((curr_mask & (prev_mask << 1)) != 0) continue;
                    // No student in upper-right
                    if ((curr_mask & (prev_mask >> 1)) != 0) continue;

                    next_dp[curr_mask] = max(next_dp[curr_mask], dp[prev_mask] + students_in_curr);
                }
            }
            dp = move(next_dp);
        }

        int ans = 0;
        for (int val : dp) {
            ans = max(ans, val);
        }
        return ans;
    }
};
```

