    int maxCompatibilitySum(std::vector<std::vector<int>>& students, std::vector<std::vector<int>>& mentors) {
        int m = students.size();
        int n = students[0].size();

        std::vector<std::vector<int>> score(m, std::vector<int>(m, 0));
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < m; ++j) {
                int s = 0;
                for (int k = 0; k < n; ++k) {
                    if (students[i][k] == mentors[j][k]) {
                        s++;
                    }
                }
                score[i][j] = s;
            }
        }

        std::vector<int> dp(1 << m, 0);
        for (int mask = 0; mask < (1 << m); ++mask) {
            int i = __builtin_popcount(mask);
            if (i >= m) continue;
            for (int j = 0; j < m; ++j) {
                if (!(mask & (1 << j))) {
                    dp[mask | (1 << j)] = std::max(dp[mask | (1 << j)], dp[mask] + score[i][j]);
                }
            }
        }

        return dp[(1 << m) - 1];
    }
};
