class Solution {
public:
    int minDays(vector<int>& bloomDay, int m, int k) {
        if ((long long)m * k > bloomDay.size()) {
            return -1;
        }

        auto canMake = [&](int days) {
            int bouquets = 0;
            int flowers = 0;
            for (int day : bloomDay) {
                if (day <= days) {
                    flowers++;
                    if (flowers == k) {
                        bouquets++;
                        flowers = 0;
                    }
                } else {
                    flowers = 0;
                }
            }
            return bouquets >= m;
        };

        int low = 1, high = 1e9;
        int ans = -1;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (canMake(mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }

        return ans;
    }
};
