class Solution {
public:
    int maxSizeSlices(vector<int>& slices) {
        int total = slices.size();
        int n = total / 3;

        auto linearMax = [&](int start, int end) {
            int m = end - start + 1;
            vector<vector<int>> dp(m + 1, vector<int>(n + 1, 0));
            for (int i = 1; i <= m; ++i) {
                for (int j = 1; j <= n; ++j) {
                    dp[i][j] = dp[i - 1][j];
                    int take = slices[start + i - 1] + (i >= 2 ? dp[i - 2][j - 1] : 0);
                    dp[i][j] = max(dp[i][j], take);
                }
            }
            return dp[m][n];
        };

        return max(linearMax(0, total - 2), linearMax(1, total - 1));
    }
};
