class Solution {
    struct DSU {
        vector<int> parent;
        DSU(int n) : parent(n) {
            iota(parent.begin(), parent.end(), 0);
        }
        int find(int i) {
            if (parent[i] == i)
                return i;
            return parent[i] = find(parent[i]);
        }
        void unite(int i, int j) {
            int root_i = find(i);
            int root_j = find(j);
            if (root_i != root_j) {
                parent[root_i] = root_j;
            }
        }
    };

public:
    vector<bool> friendRequests(int n, vector<vector<int>>& restrictions, vector<vector<int>>& requests) {
        DSU dsu(n);
        vector<bool> result;
        result.reserve(requests.size());

        for (const auto& req : requests) {
            int u = req[0];
            int v = req[1];
            int ru = dsu.find(u);
            int rv = dsu.find(v);

            if (ru == rv) {
                result.push_back(true);
            } else {
                bool can_merge = true;
                for (const auto& res : restrictions) {
                    int rx = dsu.find(res[0]);
                    int ry = dsu.find(res[1]);

                    if ((rx == ru && ry == rv) || (rx == rv && ry == ru)) {
                        can_merge = false;
                        break;
                    }
                }

                if (can_merge) {
                    dsu.unite(ru, rv);
                    result.push_back(true);
                } else {
                    result.push_back(false);
                }
            }
        }

        return result;
    }
};
