#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    int minSessions(vector<int>& tasks, int sessionTime) {
        int n = tasks.size();
        int totalMasks = 1 << n;
        vector<pair<int, int>> dp(totalMasks, {n + 1, 0});
        dp[0] = {1, 0};

        for (int mask = 0; mask < totalMasks; ++mask) {
            for (int i = 0; i < n; ++i) {
                if (!(mask & (1 << i))) {
                    auto [sessions, time] = dp[mask];
                    if (time + tasks[i] <= sessionTime) {
                        dp[mask | (1 << i)] = min(dp[mask | (1 << i)], {sessions, time + tasks[i]});
                    } else {
                        dp[mask | (1 << i)] = min(dp[mask | (1 << i)], {sessions + 1, tasks[i]});
                    }
                }
            }
        }

        return dp[totalMasks - 1].first;
    }
};
