#include <string>
#include <vector>

using namespace std;

class Solution {
    int memo[31][31][31];

    bool solve(const string& s1, const string& s2, int i, int j, int len) {
        if (memo[i][j][len] != -1) return memo[i][j][len];

        if (len == 1) {
            return memo[i][j][len] = (s1[i] == s2[j]);
        }

        int count[26] = {0};
        for (int k = 0; k < len; ++k) {
            count[s1[i + k] - 'a']++;
            count[s2[j + k] - 'a']--;
        }
        for (int c = 0; c < 26; ++c) {
            if (count[c] != 0) {
                return memo[i][j][len] = 0;
            }
        }

        for (int k = 1; k < len; ++k) {
            // Case 1: No swap
            if (solve(s1, s2, i, j, k) && solve(s1, s2, i + k, j + k, len - k)) {
                return memo[i][j][len] = 1;
            }
            // Case 2: Swap
            if (solve(s1, s2, i, j + len - k, k) && solve(s1, s2, i + k, j, len - k)) {
                return memo[i][j][len] = 1;
            }
        }

        return memo[i][j][len] = 0;
    }

public:
    bool isScramble(string s1, string s2) {
        int n = s1.length();
        for (int i = 0; i <= n; ++i) {
            for (int j = 0; j <= n; ++j) {
                for (int len = 0; len <= n; ++len) {
                    memo[i][j][len] = -1;
                }
            }
        }
        return solve(s1, s2, 0, 0, n);
    }
};
