using namespace std;

class Solution {
    long long countPairs(const vector<int>& a, vector<int> b) {
        sort(b.begin(), b.end());
        int m = b.size();
        long long total = 0;

        for (long long x : a) {
            long long target = x * x;
            int l = 0, r = m - 1;
            while (l < r) {
                long long prod = (long long)b[l] * b[r];
                if (prod < target) {
                    l++;
                } else if (prod > target) {
                    r--;
                } else {
                    if (b[l] == b[r]) {
                        long long count = r - l + 1;
                        total += count * (count - 1) / 2;
                        break;
                    } else {
                        int l_cnt = 1, r_cnt = 1;
                        while (l + 1 < r && b[l + 1] == b[l]) {
                            l++;
                            l_cnt++;
                        }
                        while (r - 1 > l && b[r - 1] == b[r]) {
                            r--;
                            r_cnt++;
                        }
                        total += (long long)l_cnt * r_cnt;
                        l++;
                        r--;
                    }
                }
            }
        }
        return total;
    }

public:
    int numTriplets(vector<int>& nums1, vector<int>& nums2) {
        return countPairs(nums1, nums2) + countPairs(nums2, nums1);
