An elegant and optimal way to solve this problem is using Dynamic Programming with bit manipulation (Bitmask DP).

### Method Explanation

1. **Check Basic Conditions**:
   - Calculate the total sum of `nums`. If the total sum is not divisible by `k`, it's impossible to partition it into `k` equal subsets, so return `false`.
   - The target sum for each subset is `target = total_sum / k`.
   - If any individual element in `nums` is strictly greater than `target`, return `false`.

2. **Bitmask DP**:
   - Since $n \le 16$, there are $2^{16} = 65,536$ subsets of elements, which can be represented by bitmasks from `0` to `(1 << n) - 1`.
   - Let `dp[mask]` represent the current running subset sum (modulo `target`) formed by the elements in `mask`, or `-1` if this subset of elements cannot be partitioned into valid subsets of sum `target` plus at most one incomplete subset.
   - Base case: `dp[0] = 0`.
   - Transition: For each reachable state `mask` where `dp[mask] != -1`:
     - Try adding an unused element `nums[j]` (where `(mask & (1 << j)) == 0`).
     - If `dp[mask] + nums[j] <= target`, the new state `new_mask = mask | (1 << j)` is valid, and its running sum is `(dp[mask] + nums[j]) % target`.
   - The final answer is `true` if `dp[(1 << n) - 1] == 0`, and `false` otherwise.

### C++ Source Code

```cpp
class Solution {
public:
    bool canPartitionKSubsets(vector<int>& nums, int k) {
        int totalSum = 0;
        for (int num : nums) {
            totalSum += num;
        }

        if (totalSum % k != 0) return false;
        int target = totalSum / k;

        int n = nums.size();
        sort(nums.rbegin(), nums.rend());
        if (nums[0] > target) return false;

        int numStates = 1 << n;
        vector<int> dp(numStates, -1);
        dp[0] = 0;

        for (int mask = 0; mask < numStates; ++mask) {
            if (dp[mask] == -1) continue;

            for (int j = 0; j < n; ++j) {
                if (!(mask & (1 << j))) {
                    if (dp[mask] + nums[j] <= target) {
                        dp[mask | (1 << j)] = (dp[mask] + nums[j]) % target;
                    } else {
                        // Since nums is sorted descending, if adding nums[j] exceeds target,
                        // larger elements earlier in the loop would also exceed, but
                        // here smaller elements follow, so we just continue.
                        break;
                    }
                }
            }
        }

        return dp[numStates - 1] == 0;
    }
};
