class Solution {
public:
    int splitArray(vector<int>& nums, int k) {
        long long low = 0;
        long long high = 0;
        for (int x : nums) {
            low = max(low, (long long)x);
            high += x;
        }

        auto canSplit = [&](long long maxSum) {
            int count = 1;
            long long currentSum = 0;
            for (int x : nums) {
                if (currentSum + x > maxSum) {
                    count++;
                    currentSum = x;
                } else {
                    currentSum += x;
                }
            }
            return count <= k;
        };

        while (low < high) {
            long long mid = low + (high - low) / 2;
            if (canSplit(mid)) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }

        return low;
    }
};
