class Solution {
public:
    int minStickers(vector<string>& stickers, string target) {
        int m = target.length();
        int n = stickers.size();

        vector<vector<int>> sticker_counts(n, vector<int>(26, 0));
        for (int i = 0; i < n; ++i) {
            for (char c : stickers[i]) {
                sticker_counts[i][c - 'a']++;
            }
        }

        vector<int> dp(1 << m, -1);
        dp[0] = 0;

        auto dfs = [&](auto self, int mask) -> int {
            if (dp[mask] != -1) return dp[mask];

            int first_char = -1;
            for (int i = 0; i < m; ++i) {
                if ((mask >> i) & 1) {
                    first_char = target[i] - 'a';
                    break;
                }
            }

            int ans = 1e9;
            for (int i = 0; i < n; ++i) {
                if (sticker_counts[i][first_char] == 0) continue;

                int next_mask = mask;
                auto counts = sticker_counts[i];
                for (int j = 0; j < m; ++j) {
                    if ((next_mask >> j) & 1) {
                        int c = target[j] - 'a';
                        if (counts[c] > 0) {
                            counts[c]--;
                            next_mask ^= (1 << j);
                        }
                    }
                }

                int sub = self(self, next_mask);
                if (sub != -1) {
                    ans = min(ans, 1 + sub);
                }
            }

            dp[mask] = (ans == 1e9) ? -1 : ans;
            return dp[mask];
        };

        return dfs(dfs, (1 << m) - 1);
    }
};
