    int regionsBySlashes(vector<string>& grid) {
        int n = grid.size();
        vector<vector<int>> g(3 * n, vector<int>(3 * n, 0));

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (grid[i][j] == '/') {
                    g[3 * i][3 * j + 2] = 1;
                    g[3 * i + 1][3 * j + 1] = 1;
                    g[3 * i + 2][3 * j] = 1;
                } else if (grid[i][j] == '\\') {
                    g[3 * i][3 * j] = 1;
                    g[3 * i + 1][3 * j + 1] = 1;
                    g[3 * i + 2][3 * j + 2] = 1;
                }
            }
        }

        int regions = 0;
        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        for (int i = 0; i < 3 * n; ++i) {
            for (int j = 0; j < 3 * n; ++j) {
                if (g[i][j] == 0) {
                    regions++;
                    queue<pair<int, int>> q;
                    q.push({i, j});
                    g[i][j] = 1;

                    while (!q.empty()) {
                        auto [r, c] = q.front();
                        q.pop();

                        for (auto& d : dirs) {
                            int nr = r + d[0];
                            int nc = c + d[1];
                            if (nr >= 0 && nr < 3 * n && nc >= 0 && nc < 3 * n && g[nr][nc] == 0) {
                                g[nr][nc] = 1;
                                q.push({nr, nc});
                            }
                        }
                    }
                }
            }
        }

        return regions;
    }
};
