using namespace std;

class StreamChecker {
    struct TrieNode {
        TrieNode* children[26] = {};
        bool is_end = false;
    };

    TrieNode* root;
    string history;
    int max_len = 0;

    void insert(const string& word) {
        TrieNode* curr = root;
        for (int i = (int)word.length() - 1; i >= 0; --i) {
            int idx = word[i] - 'a';
            if (!curr->children[idx]) {
                curr->children[idx] = new TrieNode();
            }
            curr = curr->children[idx];
        }
        curr->is_end = true;
    }

public:
    StreamChecker(vector<string>& words) {
        root = new TrieNode();
        for (const string& word : words) {
            insert(word);
            max_len = max(max_len, (int)word.length());
        }
    }

    bool query(char letter) {
        history.push_back(letter);
        TrieNode* curr = root;
        int n = history.length();
        int steps = min(n, max_len);
        for (int i = 0; i < steps; ++i) {
            int idx = history[n - 1 - i] - 'a';
            if (!curr->children[idx]) {
                return false;
            }
            curr = curr->children[idx];
            if (curr->is_end) {
                return true;
            }
        }
        return false;
    }
};

