```cpp
class Solution {
    int memo_min[30][30][30];
    int memo_max[30][30][30];

    pair<int, int> dfs(int n, int f, int s) {
        if (f + s == n + 1) {
            return {1, 1};
        }

        if (f + s > n + 1) {
            int nf = n + 1 - s;
            int ns = n + 1 - f;
            f = nf;
            s = ns;
        }

        if (memo_min[n][f][s] != 0) {
            return {memo_min[n][f][s], memo_max[n][f][s]};
        }

        int mid = (s <= n / 2) ? s : (n - s + 1);
        int K = (s <= n / 2) ? 0 : (2 * s - n - 1) / 2;
        int next_n = (n + 1) / 2;

        int min_round = 100, max_round = 0;

        for (int c1 = 0; c1 <= f - 1; ++c1) {
            for (int c2 = 0; c2 <= mid - 1 - f; ++c2) {
                int next_f = c1 + 1;
                int next_s = next_f + c2 + 1 + K;
                auto [cur_min, cur_max] = dfs(next_n, next_f, next_s);
                min_round = min(min_round, 1 + cur_min);
                max_round = max(max_round, 1 + cur_max);
            }
        }

        memo_min[n][f][s] = min_round;
        memo_max[n][f][s] = max_round;
        return {min_round, max_round};
    }

public:
    vector<int> earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        auto [earliest, latest] = dfs(n, firstPlayer, secondPlayer);
        return {earliest, latest};
    }
};
