        int best_node = -1;
        int max_depth = -1;

        for (int v : coprimes[nums[u]]) {
            if (!val_nodes[v].empty()) {
                if (val_nodes[v].back().first > max_depth) {
                    max_depth = val_nodes[v].back().first;
                    best_node = val_nodes[v].back().second;
                }
            }
        }

        ans[u] = best_node;

        val_nodes[nums[u]].push_back({depth, u});

        for (int v : adj[u]) {
            if (v != p) {
                dfs(v, u, depth + 1, nums);
            }
        }

        val_nodes[nums[u]].pop_back();
    }

public:
    vector<int> getCoprimes(vector<int>& nums, vector<vector<int>>& edges) {
        int n = nums.size();
        for (int i = 1; i <= 50; ++i) {
            coprimes[i].clear();
            val_nodes[i].clear();
            for (int j = 1; j <= 50; ++j) {
                if (std::gcd(i, j) == 1) {
                    coprimes[i].push_back(j);
                }
            }
        }

        adj.assign(n, vector<int>());
        for (const auto& edge : edges) {
            adj[edge[0]].push_back(edge[1]);
            adj[edge[1]].push_back(edge[0]);
        }

        ans.assign(n, -1);
        dfs(0, -1, 0, nums);

        return ans;
    }
