#include <vector>
#include <string>
#include <algorithm>

using namespace std;

class Solution {
    int assigned[128];
    bool used[10];
    bool cannot_be_zero[128];
    vector<string> w;
    string res;

    bool dfs(int col, int row, int sum) {
        if (col == res.length()) {
            return sum == 0;
        }

        if (row == w.size()) {
            int rem = sum % 10;
            char c = res[col];
            if (assigned[c] != -1) {
                if (assigned[c] != rem) return false;
                return dfs(col + 1, 0, sum / 10);
            } else {
                if (used[rem]) return false;
                if (rem == 0 && cannot_be_zero[c]) return false;
                assigned[c] = rem;
                used[rem] = true;
                bool ok = dfs(col + 1, 0, sum / 10);
                assigned[c] = -1;
                used[rem] = false;
                return ok;
            }
        }

        if (col >= w[row].length()) {
            return dfs(col, row + 1, sum);
        }

        char c = w[row][col];
        if (assigned[c] != -1) {
            return dfs(col, row + 1, sum + assigned[c]);
        }

        for (int d = 0; d <= 9; ++d) {
            if (used[d]) continue;
            if (d == 0 && cannot_be_zero[c]) continue;

            assigned[c] = d;
            used[d] = true;
            if (dfs(col, row + 1, sum + d)) return true;
            assigned[c] = -1;
            used[d] = false;
        }

        return false;
    }

public:
    bool isSolvable(vector<string>& words, string result) {
        fill(assigned, assigned + 128, -1);
        fill(used, used + 10, false);
        fill(cannot_be_zero, cannot_be_zero + 128, false);

        int max_len = 0;
        for (const string& word : words) {
            max_len = max(max_len, (int)word.length());
            if (word.length() > 1) {
                cannot_be_zero[word[0]] = true;
            }
        }

        if (result.length() > 1) {
            cannot_be_zero[result[0]] = true;
        }

        if (result.length() < max_len || result.length() > max_len + 1) {
            return false;
        }

        w = words;
        res = result;

        for (string& word : w) {
            reverse(word.begin(), word.end());
        }
        reverse(res.begin(), res.end());

        return dfs(0, 0, 0);
    }
};
